```typescript
import { URL } from "url";

function isSafeRedirect(target: string, allowedOrigin: string): boolean {
  if (target.startsWith("/") && !target.startsWith("//")) {
    return true; // relative path, safe
  }
  try {
    const parsed = new URL(target);
    return parsed.origin === allowedOrigin;
  } catch {
    return false;
  }
}

app.get("/login/callback", (req, res) => {
  const returnTo = req.query.returnTo as string || "/dashboard";
  const safeTarget = isSafeRedirect(returnTo, "https://myapp.example.com")
    ? returnTo
    : "/dashboard";
  // Authenticate user...
  res.redirect(safeTarget);
});
```

