    <div
      key={opt.value}
      role="option"
      tabIndex={-1}
      aria-selected={opt.value === selected.value}
      className="dropdown-item"
      onClick={() => {
        setSelected(opt);
        onSelect(opt.value);
        setIsOpen(false);
