### A11Y-003: No Focus Trap — Tab Key Escapes the Modal

**Severity:** Critical
**WCAG:** 2.4.3 Focus Order (Level A), 2.1.2 No Keyboard Trap (Level A — inverse concern)
**Location:** Lines 6–29 — entire modal component

**Evidence:** There is no focus management logic in this component: no `useEffect` to move focus into the modal on open, no event listener to constrain Tab/Shift+Tab cycling within the modal, and no mechanism to return focus to the trigger element on close. When the modal opens, keyboard focus remains wherever it was in the background page, and tabbing freely moves through elements behind the semi-transparent overlay. This means:
1. A keyboard user may not realize a modal has appeared.
2. A keyboard user can interact with obscured background content.

**Recommendation:**

```tsx
import { useEffect, useRef } from "react";

export function Modal({ isOpen, onClose, children }: ModalProps) {
  const modalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen || !modalRef.current) return;

    const focusableEls = modalRef.current.querySelectorAll<HTMLElement>(
      'a[href], button, textarea, input, select, [tabindex]:not([tabindex="-1"])'
    );
    const firstEl = focusableEls[0];
    const lastEl = focusableEls[focusableEls.length - 1];

    firstEl?.focus();

    function trapFocus(e: KeyboardEvent) {
      if (e.key === "Tab") {
        if (e.shiftKey && document.activeElement === firstEl) {
          e.preventDefault();
          lastEl?.focus();
        } else if (!e.shiftKey && document.activeElement === lastEl) {
          e.preventDefault();
          firstEl?.focus();
        }
      }
    }

    modalRef.current.addEventListener("keydown", trapFocus);
    return () => modalRef.current?.removeEventListener("keydown", trapFocus);
  }, [isOpen]);

  // ...
}
```

