  id: string;
  [key: string]: unknown;
}

interface ProcessDataInput {
  items?: DataItem[];
}

interface ValidationResult {
  valid: boolean;
  errors?: Array<{ field: string; message: string }>;
}

interface ValidationRule {
  test: (value: unknown) => boolean;
  message: string;
}

export function processData(data: ProcessDataInput): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  const items = data.items ?? [];
  items.forEach((item) => {
    result[item.id] = transform(item);
  });
  return result;
}

export function validateInput(input: unknown): ValidationResult {
  if (typeof input !== "object" || input === null) {
    return { valid: false, errors: [] };
  }
  const errors: ValidationResult["errors"] = [];
  for (const key of Object.keys(input)) {
    const rule: ValidationRule | undefined = rules[key];
    if (rule && !rule.test((input as Record<string, unknown>)[key])) {
      errors.push({ field: key, message: rule.message });
    }
  }
  return { valid: errors.length === 0, errors };
}
```

Similarly, `handleEvent` and `createService` should define interfaces for their parameters and return types.

