    // Log and handle; do not let the process crash
    console.error('Server error:', err);
  });
  ```
  Inside the handler, use `req.socket.remoteAddress` (the non-deprecated accessor) with a guard:
  ```typescript
  const ip = req.socket?.remoteAddress ?? 'unknown';
  ```

