```

**Recommendation**: Collect errors and surface them to the caller. At minimum, log each failure; ideally, accumulate results per operation:

```typescript
export class DataSyncService {
  async syncAll(): Promise<SyncResult> {
    const operations = [
      { name: "users", fn: () => this.syncUsers() },
      { name: "orders", fn: () => this.syncOrders() },
      { name: "payments", fn: () => this.syncPayments() },
      { name: "inventory", fn: () => this.syncInventory() },
      { name: "report", fn: () => this.generateReport() },
    ];

    const errors: Array<{ operation: string; error: Error }> = [];

    for (const op of operations) {
      try {
        await op.fn();
      } catch (e) {
        errors.push({
          operation: op.name,
          error: e instanceof Error ? e : new Error(String(e)),
        });
      }
    }

    const allFailed = errors.length === operations.length;
    return {
      status: errors.length === 0 ? "success" : allFailed ? "failure" : "partial",
      message: errors.length === 0
        ? "Sync completed"
        : `Sync completed with ${errors.length} error(s)`,
      errors,
    };
  }
}
```

