         Socket socket = server.accept();
         InputStream is = socket.getInputStream()) {
        ObjectMapper mapper = new ObjectMapper();
        // Deserialize to a known, safe type — never Object
        return mapper.readValue(is, MyExpectedType.class);
    }
}
