```java
import com.fasterxml.jackson.databind.ObjectMapper;

public class DataReceiver {
    private static final ObjectMapper mapper = new ObjectMapper();

    public MyDataClass receiveData(int port) throws Exception {
        try (ServerSocket server = new ServerSocket(port);
             Socket socket = server.accept();
             InputStream is = socket.getInputStream()) {
            // Deserialize only into the expected concrete type
            return mapper.readValue(is, MyDataClass.class);
        }
    }
}
```

**Option B: If `ObjectInputStream` is unavoidable, apply an `ObjectInputFilter` (Java 9+):**

```java
ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
ois.setObjectInputFilter(filterInfo -> {
    Class<?> clazz = filterInfo.serialClass();
    if (clazz != null) {
        // Allowlist only the exact types you expect
        if (clazz == MyExpectedClass.class || clazz == String.class) {
            return ObjectInputFilter.Status.ALLOWED;
        }
        return ObjectInputFilter.Status.REJECTED;
    }
    // Limit depth and array size to prevent resource exhaustion
    if (filterInfo.depth() > 5 || filterInfo.arrayLength() > 1000) {
        return ObjectInputFilter.Status.REJECTED;
    }
    return ObjectInputFilter.Status.UNDECIDED;
});
Object obj = ois.readObject();
```

