```csharp
[HttpGet("search")]
public IActionResult SearchUsers(string name, string role)
{
    using var connection = new SqlConnection(_connectionString);
    connection.Open();

    var sql = "SELECT Id, Name FROM Users WHERE Name LIKE @Name";
    if (!string.IsNullOrEmpty(role))
